          }
        }
        geometry Box {
          size 4 2 0.1
        }
      }
    }
  }
}

Transform {
  translation 5 0.5 6
  children Shape {
    appearance Appearance {
      material Material {
        diffuseColor 0.9 0.9 0.2
      }
    }
    geometry Box {
      size 1 1 1
    }
  }
}

Transform {
  translation -6 1 9
  children Shape {
    appearance Appearance {
      material Material {
        diffuseColor 0.2 0.9 0.9
      }
    }
    geometry Box {
      size 1 2 1
    }
  }
}

Transform {
  translation 0 2.5 -9
  children Shape {
    appearance Appearance {
      material Material {
        diffuseColor 0.9 0.2 0.9
      }
    }
    geometry Box {
      size 6 0.4 0.4
    }
  }
}

DEF LOG Script {
  inputOutput SFString hist ""
  inputOutput SFInt32  frame 30
  inputOnly   SFBool   C1_a
  inputOnly   SFTime   C1_t

  url "ecmascript:
    function C1_a (v, t) { hist = hist + ' ' + frame + ':C1.isActive=' + v + '@' + (t - 946684800) .toFixed (6); }
    function C1_t (v, t) { hist = hist + ' ' + frame + ':C1.collideTime=' + (v - 946684800) .toFixed (6); }
    function prepareEvents () { frame = frame + 1; }
"
}

ROUTE C1.isActive TO LOG.C1_a
ROUTE C1.collideTime TO LOG.C1_t

